import pandas as pd

def clean(df):
    df = df.drop_duplicates(subset=["penguin_id"], keep="first")
    df["species"] = df["species"].str.title()
    df["body_mass_g"] = pd.to_numeric(df["body_mass_g"], errors="coerce")
    return df

def answer(df):
    grouped = df.groupby("species")["body_mass_g"].sum().reset_index()
    result = {row["species"]: row["body_mass_g"] for _, row in grouped.iterrows() if pd.notna(row["species"]) and pd.notna(row["body_mass_g"])}
    return result
